CREATE TABLE IF NOT EXISTS etapas(id TEXT PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS contactos(id TEXT PRIMARY KEY, nombre TEXT NOT NULL, telefono TEXT, tipo TEXT NOT NULL CHECK(tipo IN ('Cara a cara','Grupos')), etapa TEXT REFERENCES etapas(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS pestanas(id TEXT PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, detalle TEXT);
CREATE TABLE IF NOT EXISTS asignaciones(id TEXT PRIMARY KEY, contacto TEXT NOT NULL REFERENCES contactos(id) ON DELETE CASCADE, pestana TEXT NOT NULL REFERENCES pestanas(id) ON DELETE CASCADE, UNIQUE(contacto,pestana));
CREATE TABLE IF NOT EXISTS notas(id TEXT PRIMARY KEY, contacto TEXT NOT NULL REFERENCES contactos(id) ON DELETE CASCADE, tema TEXT NOT NULL, texto TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recordatorios(id TEXT PRIMARY KEY, contacto TEXT NOT NULL REFERENCES contactos(id) ON DELETE CASCADE, tema TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cronograma(id TEXT PRIMARY KEY, contacto TEXT NOT NULL REFERENCES contactos(id) ON DELETE CASCADE, texto TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS respuestas(id TEXT PRIMARY KEY, nombre TEXT NOT NULL, texto TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campanas(id TEXT PRIMARY KEY, nombre TEXT NOT NULL, texto TEXT NOT NULL, fecha TEXT);
CREATE TABLE IF NOT EXISTS destinatarios(id TEXT PRIMARY KEY, campana TEXT NOT NULL REFERENCES campanas(id) ON DELETE CASCADE, contacto TEXT NOT NULL REFERENCES contactos(id) ON DELETE CASCADE, UNIQUE(campana,contacto));
CREATE TABLE IF NOT EXISTS flujos(id TEXT PRIMARY KEY, nombre TEXT NOT NULL, clave TEXT NOT NULL, coincidencia TEXT NOT NULL CHECK(coincidencia IN ('Exacta','Contiene')), texto TEXT NOT NULL, opciones TEXT);
CREATE TABLE IF NOT EXISTS ia(id TEXT PRIMARY KEY, nombre TEXT NOT NULL, modelo TEXT, contexto TEXT, instrucciones TEXT);

